<!doctype html><html lang="id"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px;color:#183047}h1{font-size:19px;margin-bottom:3px}h2{font-size:13px;margin-top:20px}p{line-height:1.5}table{width:100%;border-collapse:collapse;margin-top:8px}td,th{border:1px solid #cad5dd;padding:8px;text-align:left;vertical-align:top}th{width:28%;background:#eaf2f7}.note{white-space:pre-wrap;min-height:130px;border:1px solid #cad5dd;padding:12px}.muted{color:#627789}</style></head><body><h1>Draf Cerapan Pengujian UTTP</h1><p class="muted">Setimbang · UPT Metrologi Legal Kabupaten Rembang</p><table><tr><th>Permohonan</th><td><?= e($request->request_no) ?></td></tr><tr><th>Pemohon</th><td><?= e($request->organization_name ?: $request->full_name) ?></td></tr><tr><th>UTTP</th><td><?= (int)$item->unit_sequence ?> · <?= e($item->uttp_name) ?> · <?= e($item->brand) ?> · <?= e($item->type_name ?: '—') ?></td></tr><tr><th>Nomor seri / kapasitas</th><td><?= e($item->serial_number ?: '—') ?> / <?= e($item->capacity ?: '—') ?></td></tr><tr><th>Lokasi</th><td><?= e($item->service_address ?: $request->service_address) ?></td></tr><tr><th>Penera</th><td><?= e($request->penera_display ?: '—') ?></td></tr><tr><th>CTT</th><td><?php if (!$ctts): ?>Tidak digunakan<?php else: foreach ($ctts as $ctt): ?><?= e($ctt->option_label) ?> (<?= e($ctt->option_code) ?>)<br><?php endforeach; endif; ?></td></tr></table><h2>Catatan pengujian</h2><div class="note"><?= nl2br(e($observation)) ?></div><p><strong>Dicatat oleh:</strong> <?= e($actor->full_name) ?><br><strong>Waktu:</strong> <?= e(date('d-m-Y H:i')) ?> WIB</p><p class="muted">Draf internal untuk pemeriksaan. Dokumen ini bukan SKHP.</p></body></html>
